// === Tab: mySketch ===
/**
 * Inside the Mandelbulb — OpenProcessing.org (p5.js WEBGL)
 * Original GLSL CC0 by mrange
 * GLSL ES 3.00 — direct port of Shadertoy source
 */

const VERT = `#version 300 es
precision highp float;
in  vec3 aPosition;
in  vec2 aTexCoord;
out vec2 vTexCoord;
void main() {
  vTexCoord   = aTexCoord;
  vec4 pos    = vec4(aPosition, 1.0);
  pos.xy      = pos.xy * 2.0 - 1.0;
  gl_Position = pos;
}`;

const FRAG = `#version 300 es
precision highp float;

uniform float uTime;
uniform vec2  uResolution;
out vec4 fragColor;

#define PI              3.141592654
#define TAU             (2.0*PI)
#define PHI             (sqrt(5.0)*0.5+0.5)
#define LOOPS           2
#define POWER           8.0
#define TOLERANCE       0.0001
#define MAX_RAY_LENGTH  20.0
#define MAX_RAY_MARCHES 60
#define NORM_OFF        0.001
#define MAX_BOUNCES     5

mat3 g_rot  = mat3(1.0);
vec3 g_mat  = vec3(0.0);
vec3 g_beer = vec3(0.0);

const vec4 hsv2rgb_K = vec4(1.0,2.0/3.0,1.0/3.0,3.0);
vec3 hsv2rgb(vec3 c) {
  vec3 p=abs(fract(c.xxx+hsv2rgb_K.xyz)*6.0-hsv2rgb_K.www);
  return c.z*mix(hsv2rgb_K.xxx,clamp(p-hsv2rgb_K.xxx,0.0,1.0),c.y);
}
#define HSV2RGB(c) (c.z*mix(hsv2rgb_K.xxx,clamp(abs(fract(c.xxx+hsv2rgb_K.xyz)*6.0-hsv2rgb_K.www)-hsv2rgb_K.xxx,0.0,1.0),c.y))

const float hoff      = 0.0;
const vec3 skyCol     = HSV2RGB(vec3(hoff+0.6,  0.86, 1.0));
const vec3 glowCol    = HSV2RGB(vec3(hoff+0.065,0.8,  6.0));
const vec3 diffuseCol = HSV2RGB(vec3(hoff+0.6,  0.85, 1.0));
const vec3 lightPos   = vec3(0.0,10.0,0.0);
const float initt     = 0.1;

vec3 sRGB(vec3 t) {
  return mix(1.055*pow(t,vec3(1.0/2.4))-0.055, 12.92*t, step(t,vec3(0.0031308)));
}
vec3 aces_approx(vec3 v) {
  v=max(v,0.0)*0.6;
  float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14;
  return clamp((v*(a*v+b))/(v*(c*v+d)+e),0.0,1.0);
}

float box(vec2 p, vec2 b) {
  vec2 d=abs(p)-b;
  return length(max(d,0.0))+min(max(d.x,d.y),0.0);
}
float rayPlane(vec3 ro, vec3 rd, vec4 p) {
  return -(dot(ro,p.xyz)+p.w)/dot(rd,p.xyz);
}

float mandelBulb(vec3 p) {
  vec3 z=p; float dr=1.0,r=0.0;
  for (int i=0;i<LOOPS;i++) {
    r=length(z);
    if (r>2.0) continue;
    float theta=atan(z.y,z.x);
    float phi=asin(z.z/r)+uTime*0.2;
    dr=pow(r,POWER-1.0)*dr*POWER+1.0;
    r=pow(r,POWER); theta*=POWER; phi*=POWER;
    z=r*vec3(cos(theta)*cos(phi),sin(theta)*cos(phi),sin(phi))+p;
  }
  return 0.5*log(r)*r/dr;
}

mat3 rot_x(float a){float c=cos(a),s=sin(a);return mat3(1,0,0,0,c,s,0,-s,c);}
mat3 rot_y(float a){float c=cos(a),s=sin(a);return mat3(c,0,s,0,1,0,-s,0,c);}

vec3 skyColor(vec3 ro, vec3 rd) {
  vec3 col=clamp(vec3(0.0025/abs(rd.y))*skyCol,0.0,1.0);
  float tp0=rayPlane(ro,rd,vec4(0,1,0,4));
  float tp1=rayPlane(ro,rd,vec4(0,-1,0,6));
  if (tp1>0.0) {
    vec3 pos=ro+tp1*rd;
    float db=box(pos.xz,vec2(6,9))-1.0;
    col+=vec3(4.0)*skyCol*rd.y*rd.y*smoothstep(0.25,0.0,db);
    col+=vec3(0.8)*skyCol*exp(-0.5*max(db,0.0));
  }
  if (tp0>0.0) {
    vec3 pos=ro+tp0*rd;
    float ds=length(pos.xz)-0.5;
    col+=vec3(0.25)*skyCol*exp(-0.5*max(ds,0.0));
  }
  return clamp(col,0.0,10.0);
}

float df(vec3 p) {
  p*=g_rot;
  const float z1=2.0;
  float d1=mandelBulb(p/z1)*z1;
  g_mat  = vec3(0.8,0.5,1.0-0.025);
  g_beer = -HSV2RGB(vec3(0.05,0.95,2.0));
  return d1;
}

vec3 calcNormal(vec3 pos) {
  vec2 e=vec2(NORM_OFF,0.0);
  return normalize(vec3(
    df(pos+e.xyy)-df(pos-e.xyy),
    df(pos+e.yxy)-df(pos-e.yxy),
    df(pos+e.yyx)-df(pos-e.yyx)
  ));
}

float rayMarch(vec3 ro, vec3 rd, float dfactor) {
  float t=0.0;
  for (int i=0;i<MAX_RAY_MARCHES;i++) {
    if (t>MAX_RAY_LENGTH){t=MAX_RAY_LENGTH;break;}
    float d=dfactor*df(ro+rd*t);
    if (d<TOLERANCE) break;
    t+=d;
  }
  return t;
}

vec3 render(vec3 ro, vec3 rd) {
  vec3 agg=vec3(0), ragg=vec3(1);
  bool isInside=df(ro)<0.0;
  for (int bounce=0;bounce<MAX_BOUNCES;bounce++) {
    if (min(min(ragg.x,ragg.y),ragg.z)<0.025) break;
    float dfactor=isInside?-1.0:1.0;
    float st=rayMarch(ro,rd,dfactor);
    vec3 mat=g_mat;
    if (st>=MAX_RAY_LENGTH){agg+=ragg*skyColor(ro,rd);break;}
    vec3 sp=ro+rd*st;
    vec3 sn=dfactor*calcNormal(sp);
    float fre=1.0+dot(rd,sn); fre=mix(0.1,1.0,fre*fre);
    vec3 ld=normalize(lightPos-sp);
    float dif=max(dot(ld,sn),0.0);
    vec3 refl=reflect(rd,sn);
    float re=mat.z, ire=1.0/re;
    vec3 refr=refract(rd,sn,isInside?ire:re);
    vec3 rsky=skyColor(sp,refl);
    vec3 col=vec3(0);
    col+=diffuseCol*dif*dif*(1.0-mat.x);
    float edge=smoothstep(1.0,0.9,fre);
    col+=rsky*mat.y*fre*edge;
    if (isInside) ragg*=exp(-st*g_beer);
    agg+=ragg*col;
    if (refr==vec3(0.0)){rd=refl;}
    else{ragg*=mat.x;isInside=!isInside;rd=refr;}
    ro=sp+initt*rd;
  }
  return agg;
}

void main() {
  vec2 q=gl_FragCoord.xy/uResolution.xy;
  vec2 p=-1.0+2.0*q;
  p.x*=uResolution.x/uResolution.y;

  g_rot=rot_x(0.2*uTime)*rot_y(0.3*uTime);
  vec3 ro=0.6*vec3(0.0,2.0,5.0);
  vec3 la=vec3(0.0);
  vec3 up=vec3(0.0,1.0,0.0);
  vec3 ww=normalize(la-ro);
  vec3 uu=normalize(cross(up,ww));
  vec3 vv=normalize(cross(ww,uu));
  float fov=tan(TAU/6.0);
  vec3 rd=normalize(-p.x*uu+p.y*vv+fov*ww);

  vec3 col=render(ro,rd);
  col=aces_approx(col);
  col=sRGB(col);
  fragColor=vec4(col,1.0);
}`;

let bulbShader;

function setup() {
  createCanvas(3840, 2160, WEBGL);
  pixelDensity(1);
  noStroke();
  bulbShader = createShader(VERT, FRAG);
}

function draw() {
  shader(bulbShader);
  bulbShader.setUniform('uTime',       millis()/1000.0);
  bulbShader.setUniform('uResolution', [width, height]);
  rect(0, 0, width, height);
}

function windowResized() {
  resizeCanvas(width, height);
}

function mouseClicked(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

